class Solution {
public:
    vector<int> maxDepthAfterSplit(string seq) {
        vector<int> res;
        res.reserve(seq.size());
        int depth = 0;
        for (char c : seq) {
            if (c == '(') {
                res.push_back(depth % 2);
                depth++;
            } else {
                depth--;
                res.push_back(depth % 2);
            }
        }
        return res;
    }
};

class Solution {
    public int[] maxDepthAfterSplit(String seq) {
        int[] res = new int[seq.length()];
        int depth = 0;
        for (int i = 0; i < seq.length(); i++) {
            if (seq.charAt(i) == '(') {
                res[i] = depth % 2;
                depth++;
            } else {
                depth--;
                res[i] = depth % 2;
            }
        }
        return res;
    }
}

var maxDepthAfterSplit = function(seq) {
    const res = new Array(seq.length);
    let depth = 0;
    for (let i = 0; i < seq.length; i++) {
        if (seq[i] === '(') {
            res[i] = depth % 2;
            depth++;
        } else {
            depth--;
            res[i] = depth % 2;
        }
    }
    return res;
};
